def clean_name(n):
    s = n.replace("\u2063", "").replace("\u200b", "").strip()
    s = re.sub(r"^[\W\d_]*?(?=[A-Za-z])", "", s) if re.match(r"^[&⁉\u200b\d\.\s:]+", s) and not re.match(r"^\d+\s*(cal|fried)", s, re.I) else s
    s = re.sub(r"^(and|&)\s+", "", s, flags=re.I)
    s = re.sub(r"\s+=\s+.*$", "", s)
    s = re.sub(r"\s*(>>>|…|⤵|⬇|⇩)+\s*", " ", s)
    s = re.sub(r"\b(asmr cooking|asmr|recipe insta|recipe)\s*$", "", s, flags=re.I).strip()
    s = s.replace("’S", "’s").replace("'S", "'s").replace("’Ll", "’ll").replace("’M", "’m").replace("’D", "’d").replace("’Ve", "’ve").replace("Bbq", "BBQ").replace("Kfc", "KFC")
    return re.sub(r"\s+", " ", s).strip(" -:+&")
